FuncDef.Code:
vec3 backdropAnimatedVerticalGradient(in vec3 dir, in vec3 colorTop, in vec3 colorBottom, in float animSpeed, in float animAmp)
{
    vec3 color = mix(colorBottom, colorTop, dir.y * 0.5 + 0.5);

    color += animAmp * vec3( sin(1.36 * iTime * animSpeed),
                             sin(1.22 * iTime * animSpeed),
                             sin(1.54 * iTime * animSpeed) );

    color = clamp(color, 0.0, 1.0);

    return color;
}
